insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('vimba-private-documents','vimba-private-documents',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy vimba_documents_select on storage.objects for select to authenticated using(bucket_id='vimba-private-documents' and (select private.is_internal()) and (select private.can_access_tenant(((storage.foldername(name))[1])::uuid)));
create policy vimba_documents_insert on storage.objects for insert to authenticated with check(bucket_id='vimba-private-documents' and (select private.is_internal()) and (select private.can_access_tenant(((storage.foldername(name))[1])::uuid)));
create policy vimba_documents_update on storage.objects for update to authenticated using(bucket_id='vimba-private-documents' and (select private.is_internal()) and (select private.can_access_tenant(((storage.foldername(name))[1])::uuid))) with check(bucket_id='vimba-private-documents' and (select private.is_internal()) and (select private.can_access_tenant(((storage.foldername(name))[1])::uuid)));
create policy vimba_documents_delete on storage.objects for delete to authenticated using(bucket_id='vimba-private-documents' and (select private.has_role(array['platform_owner','super_administrator','administrator','hr','compliance']::public.app_role[])) and (select private.can_access_tenant(((storage.foldername(name))[1])::uuid)));
